generator_matlab:
source_root = '/path/to/CT-FIRE3.0_src';
addpath(fullfile(source_root,'FIRE','initproc'),'-begin');
shapes = {[3 4], [1 3 4], [3 3 4], [1 7], [3 1 4], [1 1 7], [5 7 3]};
cases = struct('name',{},'input',{},'sigma',{},'expected',{});
for si=1:numel(shapes)
    sz=shapes{si};
    base=reshape(mod((0:prod(sz)-1)*17,53)/7,sz);
    if numel(sz)==2
        anis=[0.3 0.7]; mixed=[0 0.7];
    else
        anis=[0.3 0.7 1.2]; mixed=[0 0.7 1.2];
    end
    sigmas={0,0.3,0.5,1,2,anis,mixed};
    for ti=1:2
        if ti==1, input=single(base); kind='single'; else, input=base; kind='double'; end
        for gi=1:numel(sigmas)
            sigma=sigmas{gi};
            expected=smooth(input,sigma);
            ci=numel(cases)+1;
            cases(ci).name=sprintf('shape%d_%s_sigma%d',si,kind,gi);
            cases(ci).input=input;
            cases(ci).sigma=sigma;
            cases(ci).expected=expected;
        end
    end
end
matlab_version=version;
source=which('smooth');
save('matlab-cases.mat','cases','matlab_version','source','-v7');
fprintf('Generated %d cases using %s\n',numel(cases),source);
